@using sv_c1d853f26b8d4b60bf2b316fe8a883a3.Models

<nav class="step-indicator" aria-label="Application steps">
    <ol class="step-list">
        @for (int i = 0; i < Steps.Length; i++)
        {
            var step = i;
            var status = GetStepStatus(step);
            <li class="step-item @status" @onclick="() => OnStepClick(step)" role="button" aria-current="@(step == CurrentStep ? "step" : null)">
                <span class="step-icon">
                    @if (status == "completed")
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </span>
                <span class="step-label">@Steps[step]</span>
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] Steps = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "active";
        if (CompletedSteps.Contains(step)) return "completed";
        return "dimmed";
    }

    private async Task OnStepClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

