@using sv_c1d853f26b8d4b60bf2b316fe8a883a3.Models

<div class="step-content">
    <h3>Review & Submit</h3>

    @if (IsSubmitted)
    {
        <div class="confirmation">
            <h4>&#10003; Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
        </div>
    }
    else
    {
        <section class="review-section">
            <h4>Personal Information <a class="edit-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</a></h4>
            <dl>
                <dt>Full Name</dt><dd>@Personal?.FullName</dd>
                <dt>Email</dt><dd>@Personal?.Email</dd>
                <dt>Phone</dt><dd>@Personal?.Phone</dd>
                <dt>Address</dt><dd>@Personal?.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <h4>Work History <a class="edit-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</a></h4>
            @if (Work?.Entries is not null)
            {
                @foreach (var entry in Work.Entries)
                {
                    <div class="review-entry">
                        <strong>@entry.Title</strong> at @entry.Company<br />
                        <span>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")</span>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p>@entry.Description</p>
                        }
                    </div>
                }
            }
        </section>

        <section class="review-section">
            <h4>References <a class="edit-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</a></h4>
            @if (References is not null)
            {
                @foreach (var r in References)
                {
                    <div class="review-entry">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
                        @r.Email &bull; @r.Phone
                    </div>
                }
            }
        </section>

        <section class="review-section">
            <h4>Cover Letter <a class="edit-link" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</a></h4>
            <p class="cover-letter-preview">@CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="error-message">@ErrorMessage</div>
        }

        <div class="step-buttons">
            <button type="button" class="btn-back" @onclick="OnBack">Back</button>
            <button type="button" class="btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public WorkHistory? Work { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public Func<Task<int>>? SubmitApplication { get; set; }

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? ErrorMessage;

    private async Task HandleSubmit()
    {
        if (SubmitApplication is null) return;

        IsSubmitting = true;
        ErrorMessage = null;

        try
        {
            ApplicationId = await SubmitApplication();
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}

