toolArgs.file_text:
.application-form {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    cursor: default;
}

.step-item.completed {
    cursor: pointer;
}

.step-icon {
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    margin-bottom: 0.5rem;
    border: 2px solid #ccc;
    background: white;
    color: #999;
}

.step-item.active .step-icon {
    border-color: #0d6efd;
    background: #0d6efd;
    color: white;
}

.step-item.completed .step-icon {
    border-color: #198754;
    background: #198754;
    color: white;
}

.step-item.dimmed .step-icon {
    border-color: #dee2e6;
    color: #adb5bd;
}

.step-label {
    font-size: 0.8rem;
    text-align: center;
    color: #666;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.dimmed .step-label {
    color: #adb5bd;
}

/* Form elements */
.step-content {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1.5rem;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #ced4da;
    border-radius: 0.25rem;
    font-size: 1rem;
}

.form-group textarea {
    resize: vertical;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #dee2e6;
}

.btn-next, .btn-submit {
    padding: 0.5rem 1.5rem;
    background: #0d6efd;
    color: white;
    border: none;
    border-radius: 0.25rem;
    cursor: pointer;
    font-size: 1rem;
    margin-left: auto;
}

.btn-next:hover, .btn-submit:hover {
    background: #0b5ed7;
}

.btn-next:disabled, .btn-submit:disabled {
    background: #6c757d;
    cursor: not-allowed;
}

.btn-back {
    padding: 0.5rem 1.5rem;
    background: #6c757d;
    color: white;
    border: none;
    border-radius: 0.25rem;
    cursor: pointer;
    font-size: 1rem;
}

.btn-back:hover {
    background: #5a6268;
}

.btn-add {
    padding: 0.4rem 1rem;
    background: #198754;
    color: white;
    border: none;
    border-radius: 0.25rem;
    cursor: pointer;
    margin-bottom: 1rem;
}

.btn-add:hover {
    background: #157347;
}

.btn-remove {
    float: right;
    padding: 0.25rem 0.75rem;
    background: #dc3545;
    color: white;
    border: none;
    border-radius: 0.25rem;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-remove:hover {
    background: #bb2d3b;
}

/* Errors */
.error-message {
    color: #dc3545;
    background: #f8d7da;
    border: 1px solid #f5c2c7;
    padding: 0.75rem;
    border-radius: 0.25rem;
    margin-top: 1rem;
}

.field-error {
    color: #dc3545;
    font-size: 0.85rem;
}

/* Character count */
.char-count {
    display: block;
    text-align: right;
    color: #6c757d;
    font-size: 0.85rem;
    margin-top: 0.25rem;
}

/* Work entry / reference editors */
.work-entry-editor,
.reference-editor {
    border: 1px solid #e9ecef;
    border-radius: 0.25rem;
    padding: 1rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

/* Review step */
.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid #dee2e6;
}

.review-section h4 {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.edit-link {
    font-size: 0.85rem;
    color: #0d6efd;
    cursor: pointer;
    text-decoration: underline;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0.5rem 0;
}

.review-section dt {
    font-weight: 600;
    color: #495057;
}

.review-entry {
    margin: 0.5rem 0;
    padding: 0.5rem;
    background: #f8f9fa;
    border-radius: 0.25rem;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 0.25rem;
}

.confirmation {
    text-align: center;
    padding: 2rem;
    background: #d1e7dd;
    border: 1px solid #badbcc;
    border-radius: 0.5rem;
}

.confirmation h4 {
    color: #0f5132;
}

