+    background: #0d6efd;
+    color: white;
+    border: none;
+    border-radius: 0.25rem;
+    cursor: pointer;
+    font-size: 1rem;
+    margin-left: auto;
+}
+
+.btn-next:hover, .btn-submit:hover {
+    background: #0b5ed7;
+}
+
+.btn-next:disabled, .btn-submit:disabled {
+    background: #6c757d;
+    cursor: not-allowed;
+}
+
+.btn-back {
+    padding: 0.5rem 1.5rem;
+    background: #6c757d;
+    color: white;
+    border: none;
+    border-radius: 0.25rem;
+    cursor: pointer;
+    font-size: 1rem;
+}
+
+.btn-back:hover {
+    background: #5a6268;
+}
+
+.btn-add {
+    padding: 0.4rem 1rem;
+    background: #198754;
+    color: white;
+    border: none;
+    border-radius: 0.25rem;
+    cursor: pointer;
+    margin-bottom: 1rem;
+}
+
+.btn-add:hover {
+    background: #157347;
+}
+
+.btn-remove {
+    float: right;
+    padding: 0.25rem 0.75rem;
+    background: #dc3545;
+    color: white;
+    border: none;
+    border-radius: 0.25rem;
+    cursor: pointer;
+    font-size: 0.85rem;
+}
+
+.btn-remove:hover {
+    background: #bb2d3b;
+}
+
+/* Errors */
+.error-message {
+    color: #dc3545;
+    background: #f8d7da;
+    border: 1px solid #f5c2c7;
+    padding: 0.75rem;
+    border-radius: 0.25rem;
+    margin-top: 1rem;
+}
+
+.field-error {
+    color: #dc3545;
+    font-size: 0.85rem;
+}
+
+/* Character count */
+.char-count {
+    display: block;
+    text-align: right;
+    color: #6c757d;
+    font-size: 0.85rem;
+    margin-top: 0.25rem;
+}
+
+/* Work entry / reference editors */
+.work-entry-editor,
+.reference-editor {
+    border: 1px solid #e9ecef;
+    border-radius: 0.25rem;
+    padding: 1rem;
+    margin-bottom: 1rem;
+    background: #f8f9fa;
+}
+
+/* Review step */
+.review-section {
+    margin-bottom: 1.5rem;
+    padding-bottom: 1rem;
+    border-bottom: 1px solid #dee2e6;
+}
+
+.review-section h4 {
+    display: flex;
+    align-items: center;
+    gap: 1rem;
+}
+
+.edit-link {
+    font-size: 0.85rem;
+    color: #0d6efd;
+    cursor: pointer;
+    text-decoration: underline;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: auto 1fr;
+    gap: 0.25rem 1rem;
+    margin: 0.5rem 0;
+}
+
+.review-section dt {
+    font-weight: 600;
+    color: #495057;
+}
+
+.review-entry {
+    margin: 0.5rem 0;
+    padding: 0.5rem;
+    background: #f8f9fa;
+    border-radius: 0.25rem;
+}
+
+.cover-letter-preview {
+    white-space: pre-wrap;
+    background: #f8f9fa;
+    padding: 1rem;
+    border-radius: 0.25rem;
+}
+
+.confirmation {
+    text-align: center;
+    padding: 2rem;
